Boolean exec_q_free_add( Q q_free  , UInt8 size_of_message )
{
	Q_Msg * q_msg = (Q_Msg *)os_mem_request ( size_of_message ) ;
		
	if( q_msg )
	{
		q_assign (q_free , q_msg) ;
	
		q_insert (q_free , q_msg) ;
	}
	return !!q_msg;
}	

